import os
from playwright.sync_api import sync_playwright
with sync_playwright() as p:
 b=p.chromium.launch(headless=True,executable_path=os.getenv('CHROME_PATH'),args=['--enable-unsafe-swiftshader']); page=b.new_page(viewport={'width':1440,'height':900}); errors=[];page.on('pageerror',lambda e:errors.append(str(e))); page.on('requestfailed',lambda r:errors.append('request failed: '+r.url+' '+str(r.failure)))
 page.goto(os.getenv('URBANPULSE_URL', 'http://127.0.0.1:5173'));page.get_by_text('10,776,622').first.wait_for(timeout=30000); print('overview OK')
 page.get_by_role('button',name='Mobility Atlas',exact=True).click(); page.locator('.maplibregl-canvas').wait_for();page.wait_for_timeout(3500); c=page.locator('.maplibregl-canvas').bounding_box();page.mouse.move(c['x']+c['width']*.5,c['y']+c['height']*.42);page.mouse.click(c['x']+c['width']*.5,c['y']+c['height']*.42);page.get_by_text('LOCATION ID',exact=False).wait_for(); page.get_by_role('button',name='Drop-offs').click();assert 'on' in page.get_by_role('button',name='Drop-offs').get_attribute('class');print('atlas selection/dropoff OK')
 page.get_by_role('button',name='Temporal Intelligence',exact=True).click();page.get_by_text('Weekly rhythm').wait_for();page.get_by_label('Start date').fill('2025-02-01');page.wait_for_timeout(1000);page.get_by_label('Start date').fill('2025-01-01');page.wait_for_timeout(1000);print('date filters OK')
 page.get_by_role('button',name='Flow Explorer',exact=True).click();page.get_by_label('Origin zone').select_option(label='Midtown Center');page.wait_for_timeout(1500);assert page.get_by_label('Origin zone').input_value()=='161';page.get_by_text('Connections across zones').scroll_into_view_if_needed();page.get_by_label('Origin zone').select_option(label='All origins');print('flows OK')
 page.get_by_role('button',name='Forecasting Lab',exact=True).click();page.get_by_text('381.46').wait_for();page.get_by_text('Expanding-window validation').wait_for();print('forecast OK')
 page.get_by_role('button',name='Hotspot Intelligence',exact=True).click();page.get_by_text('Where the profiles occur').wait_for();print('clustering OK')
 page.get_by_role('button',name='Scenario Studio',exact=True).click();page.locator('.scenario').wait_for();before=page.locator('.scenario').inner_text();page.get_by_label('Demand adjustment').fill('50');page.wait_for_timeout(1500);assert before != page.locator('.scenario').inner_text(); print('scenario OK')
 page.get_by_role('button',name='Data Observatory',exact=True).click();page.get_by_text('11,198,026').wait_for();print('quality OK; errors:',errors);assert not errors;b.close()
